def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        return sum(1 for char in txt if char.islower() and (ord(char) - ord('a')) % 2 == 1)

import hashlib

def string_to_md5(text):
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()

from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    stack = []
    current_group = []

    for char in paren_string.replace(" ", ""):
        if char == '(':
            stack.append(char)
            current_group.append(char)
        elif char == ')':
            stack.pop()
            current_group.append(char)
            if not stack:
                result.append(''.join(current_group))
                current_group = []

    return result

import re

def fruit_distribution(s, n):
    numbers = map(int, re.findall(r'\d+', s))
    return n - sum(numbers)

def next_smallest(lst):
    unique_sorted_lst = sorted(set(lst))
    return unique_sorted_lst[1] if len(unique_sorted_lst) > 1 else None

